const r = await tools.exec_command({cmd:"cat "$STAMPED_ASSESSMENT_SOURCE/../skills/stamped-conventions/checklist/lock.json" 2>/dev/null || true; printf '\n--- judge target metadata ---\n'; cat "$STAMPED_JUDGE_OUTPUT/judge-target.json"; printf '\n--- compact manifests/receipts ---\n'; "$STAMPED_ASSESSMENT_PYTHON" - <<'PY'
import json, os
for env in ['STAMPED_DELIVERY_MANIFEST','STAMPED_OPERATIONAL_MANIFEST','STAMPED_WORKER_STOP_RECEIPT','STAMPED_PROCEDURE','STAMPED_ASSESSMENT_PIN']:
 p=os.environ[env]; d=json.load(open(p)); print('\n',env,p)
 for k,v in d.items():
  if isinstance(v,(str,int,float,bool)) or v is None: print(k,repr(v))
  elif isinstance(v,list): print(k,'list',len(v))
  elif isinstance(v,dict): print(k,'dict keys',list(v)[:25])
 print('sha256',d.get('sha256') or d.get('capture_sha256') or d.get('delivery_capture_sha256'))
PY
printf '\n--- coordinator scientific guidance ---\n'; cat "$(dirname "$STAMPED_WORKER_STOP_RECEIPT")/frozen-inputs/coordinator-guidance/judging.md"; printf '\n--- target documentation, code, report and records ---\n'; for f in README.md report.md analysis/group_analysis.py input/upstream-methods.md input/study-task.md input/participants.tsv results/summary.json results/run.log .git/config; do if [ -f "$STAMPED_JUDGE_TARGET/$f" ]; then printf '\n### %s\n' "$f"; sed -n '1,260p' "$STAMPED_JUDGE_TARGET/$f"; fi; done","yield_time_ms":10000,"max_output_tokens":16000});
text(r.output);

const r = await tools.exec_command({cmd:"cat "$STAMPED_JUDGE_OUTPUT/2026-10-16-probes.json"; printf '\n--- receipt summary ---\n'; "$STAMPED_ASSESSMENT_PYTHON" - <<'PY'
import json,os
p=os.environ['STAMPED_WORKER_STOP_RECEIPT']; d=json.load(open(p)); print('capture',d['capture']); print('head',d['head_commit']); print('entries',len(d['entries'])); print('errors',d['errors']); print('omissions',d['omissions']); print('dependencies',d.get('git_dependencies')); print('worker',d['worker']); print('git metadata',d.get('git_metadata')); print('key artifact paths:')
for e in d['entries']:
 s=e['path']
 if any(x in s for x in ['analysis/','results/','figures/','report.md','input/']) and not s.endswith('.nii.gz'): print(s,e.get('kind'),e.get('sha256'),e.get('bytes'),e.get('mode'))
PY
printf '\n--- target path list ---\n'; find "$STAMPED_JUDGE_TARGET" -path "$STAMPED_JUDGE_TARGET/.git" -prune -o -type f -print | sed "s|$STAMPED_JUDGE_TARGET/||" | sort; printf '\n--- target symlinks ---\n'; find "$STAMPED_JUDGE_TARGET" -path "$STAMPED_JUDGE_TARGET/.git" -prune -o -type l -printf '%P -> %l\n'; printf '\n--- items ---\n'; "$STAMPED_ASSESSMENT_PYTHON" "$STAMPED_ASSESSMENT_RUNNER" response items","yield_time_ms":10000,"max_output_tokens":10000});
text(r.output);

